#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMediaLayer: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = MediaLayer

    public static func lift(_ handle: UInt64) throws -> MediaLayer {
        return MediaLayer(unsafeFromHandle: handle)
    }

    public static func lower(_ value: MediaLayer) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MediaLayer {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: MediaLayer, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeMediaLayer_lift(_ handle: UInt64) throws -> MediaLayer {
    return try FfiConverterTypeMediaLayer.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeMediaLayer_lower(_ value: MediaLayer) -> UInt64 {
    return FfiConverterTypeMediaLayer.lower(value)
}






/**
 * One mounted place: immutable item, unique id, released at most once.
 */
public protocol MediaPlaceProtocol: AnyObject, Sendable {
    
    func itemState(state: MediaState) throws 
    
    func release() 
    
    func seek(fraction: Double) throws 
    
    func update(input: PlaceInput) throws 
    
}
/**
 * One mounted place: immutable item, unique id, released at most once.
 */
open class MediaPlace: MediaPlaceProtocol, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_medialayer_fn_clone_mediaplace(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_medialayer_fn_free_mediaplace(handle, $0) }
    }

    

    
