        self.turn = turn
        self.upright = upright
        self.crop = crop
        self.mirror = mirror
        self.output = output
        self.needsDraw = needsDraw
        self.sample = sample
        self.decode = decode
        self.thumbnailSide = thumbnailSide
        self.cost = cost
    }

    

    
}

