    case bind(lens: CameraLens
    )
    case unbind
    case restart(lens: CameraLens
    )
    case takePhoto
    case beginRecording
    case endRecording(discard: Bool
    )
    case readClip
    case deliver
    case discard
    case setTorch(on: Bool
    )
    case setZoom(ratio: Float
    )





}

