        switch variant {

        

        
        case 1: return .InvalidLimits(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidSpec(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Fetch(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Timeout(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 5: return .BlurHash(
