public enum SlotCall: Equatable, Hashable {
    
    case load(key: String, route: PlaybackRoute, generation: UInt64
    )
    case unload
    case preroll
    case play
    case pause
    case mute
    case unmute
    case attach(viewToken: UInt64
    )
    case detach
    case seek(positionMs: UInt64
    )
    case rate(rate: Float
    )
    case readahead(ms: UInt64
    )





}

#if compiler(>=6)
extension SlotCall: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSlotCall: FfiConverterRustBuffer {
    typealias SwiftType = SlotCall

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SlotCall {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .load(key: try FfiConverterString.read(from: &buf), route: try FfiConverterTypePlaybackRoute.read(from: &buf), generation: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 2: return .unload
        
        case 3: return .preroll
        
        case 4: return .play
        
        case 5: return .pause
        
        case 6: return .mute
        
        case 7: return .unmute
        
        case 8: return .attach(viewToken: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 9: return .detach
        
        case 10: return .seek(positionMs: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 11: return .rate(rate: try FfiConverterFloat.read(from: &buf)
        )
        
        case 12: return .readahead(ms: try FfiConverterUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SlotCall, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .load(key,route,generation):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(key, into: &buf)
            FfiConverterTypePlaybackRoute.write(route, into: &buf)
            FfiConverterUInt64.write(generation, into: &buf)
            
        
        case .unload:
            writeInt(&buf, Int32(2))
        
        
        case .preroll:
            writeInt(&buf, Int32(3))
        
        
        case .play:
            writeInt(&buf, Int32(4))
        
        
        case .pause:
            writeInt(&buf, Int32(5))
        
        
        case .mute:
            writeInt(&buf, Int32(6))
        
        
        case .unmute:
            writeInt(&buf, Int32(7))
        
        
        case let .attach(viewToken):
            writeInt(&buf, Int32(8))
            FfiConverterUInt64.write(viewToken, into: &buf)
            
        
        case .detach:
            writeInt(&buf, Int32(9))
        
        
        case let .seek(positionMs):
            writeInt(&buf, Int32(10))
            FfiConverterUInt64.write(positionMs, into: &buf)
            
        
        case let .rate(rate):
            writeInt(&buf, Int32(11))
            FfiConverterFloat.write(rate, into: &buf)
            
        
        case let .readahead(ms):
            writeInt(&buf, Int32(12))
            FfiConverterUInt64.write(ms, into: &buf)
            
        }
    }
}


